-- Synthetic fixture from tests/core/synthetic.sql only. No real MASS identities.
SET ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001","role":"authenticated"}',false);
SELECT core_test.assert_true(jsonb_array_length(mass_api.get_context()->'centres')=1,'context exposes only own assigned centre');
SELECT core_test.assert_true(mass_api.get_context()#>>'{centres,0,label}'='Synthetic centre A','centre labels are server-sourced');
SELECT core_test.assert_true((mass_api.get_context()#>>'{centres,0,can_write}')::boolean,'teacher capability is server-computed');
SELECT core_test.assert_true(jsonb_array_length(mass_api.get_references()->'attendance_codes')=5,'only existing controlled attendance definitions returned');
SELECT core_test.assert_true((SELECT count(*)=3 FROM mass_api.read_students('10000000-0000-4000-8000-000000000001')),'historical episodes preserved in bounded read');
SELECT core_test.assert_true((SELECT count(*)=2 FROM mass_api.read_students('10000000-0000-4000-8000-000000000001','2026-04-01')),'as-of roster respects historical assignments');
SELECT core_test.assert_true((SELECT bool_and(full_name='Synthetic record') FROM mass_api.read_students('10000000-0000-4000-8000-000000000001')),'explicit profile capability preserves permitted fields');
SELECT core_test.assert_true((SELECT count(*)=7 FROM mass_api.read_attendance('10000000-0000-4000-8000-000000000001','2026-04-01','2026-05-01')),'attendance records carry real marks and revisions');
SELECT core_test.assert_true((SELECT count(*)=1 FROM mass_api.read_calendar('10000000-0000-4000-8000-000000000001','2026-04-01','2026-05-01')),'confirmed calendar is separate from delivery statuses');
SELECT core_test.assert_true((SELECT score=0 AND row_version=2 FROM mass_api.read_assessments('10000000-0000-4000-8000-000000000001','2026-04-01','2027-04-01')),'assessment zero and revision survive read API');
SELECT core_test.assert_true((SELECT count(*)=1 FROM mass_api.read_activities('10000000-0000-4000-8000-000000000001','2026-04-01','2026-05-01')),'named activity is source-backed');
SELECT core_test.assert_true((SELECT participated AND row_version=2 FROM mass_api.read_participation('10000000-0000-4000-8000-000000000001','2026-04-01','2026-05-01')),'participation revision available for safe corrections');
SELECT core_test.assert_true((SELECT applied IS NULL AND attended AND passed IS NULL FROM mass_api.read_morarji('10000000-0000-4000-8000-000000000001')),'Morarji unknown outcomes preserved');
SELECT core_test.expect_error($q$SELECT * FROM mass_api.read_students('10000000-0000-4000-8000-000000000002')$q$,'42501','other centre read rejected before pagination');
SELECT core_test.expect_error($q$SELECT * FROM mass_api.read_students(NULL)$q$,'42501','null centre cannot create global report');
SELECT core_test.expect_error($q$SELECT * FROM mass_api.read_students('10000000-0000-4000-8000-000000000001',NULL,101,0)$q$,'22023','unbounded page size rejected');
SELECT core_test.expect_error($q$SELECT * FROM mass_api.read_students('10000000-0000-4000-8000-000000000001',NULL,100,-1)$q$,'22023','negative pagination rejected');
SELECT core_test.expect_error($q$SELECT * FROM mass_api.read_attendance('10000000-0000-4000-8000-000000000001','2026-04-01','2028-04-01')$q$,'22023','unbounded date window rejected');
SELECT core_test.expect_error($q$SELECT * FROM mass_api.read_attendance('10000000-0000-4000-8000-000000000001',NULL,NULL)$q$,'22023','missing date window rejected');
SELECT core_test.expect_error('SELECT * FROM mass_core.user_scope_grants','42501','discovery never grants raw scope table access');
SELECT core_test.assert_true((SELECT count(user_id)=1 FROM mass_core.user_scope_grants),'column-limited scope discovery sees only own active grant');
SELECT core_test.assert_true((SELECT count(user_id)=0 FROM mass_core.user_scope_grants WHERE user_id<>'00000000-0000-4000-8000-000000000001'),'self-scope policy hides other staff grants');
SELECT core_test.expect_error('SELECT verified_by FROM mass_core.user_scope_grants','42501','verifier metadata remains private');
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000004","role":"authenticated"}',false);
SELECT core_test.assert_true(jsonb_array_length(mass_api.get_context()->'centres')=2,'Leadership sees only its explicit centre grants');
SELECT core_test.assert_true(NOT (mass_api.get_context()#>>'{centres,0,can_write}')::boolean,'Leadership remains read-only');
SELECT core_test.assert_true((SELECT bool_and(full_name IS NULL AND gender_code IS NULL AND class10_board_passed IS NULL) FROM mass_api.read_students('10000000-0000-4000-8000-000000000001')),'Leadership private fields masked by existing RLS');
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000003","role":"authenticated"}',false);
SELECT core_test.assert_true(NOT (mass_api.get_context()#>>'{centres,0,can_read_profiles}')::boolean,'CO does not gain private profile access');
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000008","role":"authenticated"}',false);
SELECT core_test.assert_true(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(mass_api.get_context()->'centres') c WHERE (c->>'can_write')::boolean),'mixed Leadership role does not gain write UI capability');
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000007","role":"Teacher","centre":"all"}',false);
SELECT core_test.assert_true(jsonb_array_length(mass_api.get_context()->'centres')=0,'expired grants and forged business claims reveal no scope');
SELECT core_test.expect_error('SELECT mass_api.get_references()','42501','unassigned reference discovery denied');
SELECT core_test.expect_error($q$SELECT * FROM mass_api.read_morarji('10000000-0000-4000-8000-000000000001')$q$,'42501','expired programme history denied');
RESET ROLE;
BEGIN;
SET ROLE mass_core_admin;
UPDATE mass_core.user_scope_grants SET ends_at='2001-01-01' WHERE user_id='00000000-0000-4000-8000-000000000001';
RESET ROLE;
SET ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001"}',true);
SELECT core_test.assert_true(jsonb_array_length(mass_api.get_context()->'centres')=0,'revocation removes discovered capabilities immediately');
SELECT core_test.expect_error($q$SELECT * FROM mass_api.read_students('10000000-0000-4000-8000-000000000001')$q$,'42501','revoked record read fails closed');
ROLLBACK;
SET ROLE anon;
SELECT core_test.expect_error('SELECT mass_api.get_context()','42501','anonymous context denied');
RESET ROLE;
-- Even accidental inherited authenticated ACLs must not admit a BYPASSRLS caller.
BEGIN;
GRANT authenticated TO service_role;
SET ROLE service_role;
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000004"}',true);
SELECT core_test.expect_error('SELECT mass_api.get_context()','42501','service role cannot use inherited context permission');
SELECT core_test.expect_error($q$SELECT * FROM mass_api.read_students('10000000-0000-4000-8000-000000000001')$q$,'42501','BYPASSRLS caller cannot bypass private-field projection');
RESET ROLE;
ROLLBACK;
SELECT core_test.assert_true((SELECT count(*)=23 AND bool_and(relrowsecurity AND relforcerowsecurity) FROM pg_class WHERE relnamespace IN ('mass_core'::regnamespace,'mass_foundation'::regnamespace) AND relkind='r'),'proposal adds no tables and preserves forced RLS');
SELECT core_test.assert_true((SELECT count(*)=72 FROM pg_policy WHERE polrelid IN (SELECT oid FROM pg_class WHERE relnamespace IN ('mass_core'::regnamespace,'mass_foundation'::regnamespace))),'proposal adds only one own-scope discovery policy');
SELECT core_test.assert_true((SELECT count(*)=20 FROM pg_proc WHERE pronamespace='mass_api'::regnamespace),'proposal adds exactly nine read RPCs');
SELECT core_test.assert_true((SELECT count(*)=0 FROM pg_proc WHERE pronamespace='mass_api'::regnamespace AND proname IN ('get_context','get_references','read_students','read_attendance','read_calendar','read_assessments','read_activities','read_participation','read_morarji') AND prosecdef),'all nine proposed read RPCs are invoker-only');
SELECT core_test.assert_true((SELECT bool_and(NOT has_function_privilege('anon',oid,'EXECUTE') AND NOT has_function_privilege('service_role',oid,'EXECUTE')) FROM pg_proc WHERE pronamespace='mass_api'::regnamespace),'no anonymous/service-role execute widening');
SET ROLE authenticated;
SELECT set_config('request.jwt.claims','{}',false);
SELECT core_test.expect_error('SELECT mass_api.get_context()','42501','authenticated role without trusted UID denied');
RESET ROLE;

SELECT core_test.assert_true((SELECT count(*)=155 FROM pg_attribute WHERE attrelid IN (SELECT oid FROM pg_class WHERE relnamespace IN ('mass_core'::regnamespace,'mass_foundation'::regnamespace) AND relkind='r') AND attnum>0 AND NOT attisdropped),'proposal preserves 155 columns');
SELECT core_test.assert_true((SELECT count(*)=27 FROM pg_constraint WHERE conrelid IN (SELECT oid FROM pg_class WHERE relnamespace IN ('mass_core'::regnamespace,'mass_foundation'::regnamespace) AND relkind='r') AND contype='f'),'proposal preserves 27 foreign keys');
SELECT core_test.assert_true((SELECT count(*)=19 FROM pg_proc WHERE prosecdef AND pronamespace IN ('mass_core'::regnamespace,'mass_foundation'::regnamespace,'mass_api'::regnamespace)),'proposal preserves 19 existing definers');
SELECT core_test.assert_true((SELECT array_agg(attname::text ORDER BY attname::text)=ARRAY['can_read_profiles','centre_id','ends_at','role_code','starts_at','user_id'] FROM pg_attribute WHERE attrelid='mass_core.user_scope_grants'::regclass AND attnum>0 AND NOT attisdropped AND has_column_privilege('authenticated',attrelid,attnum,'SELECT')),'self-discovery grants exactly six non-verifier columns');
